-- =====================================================================
-- Cuentas Claras · datos de demostración (24 meses: nov 2024 – oct 2026)
--
-- Crea el usuario «demo» (contraseña: demo1234) con categorías, reglas recurrentes,
-- movimientos, pendientes de validar y presupuestos. Generado de forma determinista.
--
-- Uso (con los contenedores en marcha):
--   docker compose exec -T db sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql -u root "$MYSQL_DATABASE"' < database/demo_data.sql
--
-- Si el usuario «demo» ya existe, el script falla en el primer INSERT sin modificar nada.
-- Para eliminarlo después: database/demo_data_remove.sql
-- =====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

SET @uid = LAST_INSERT_ID();

-- Categorías
SET @c_viv = (SELECT id FROM categories WHERE user_id = @uid AND type = 'expense' AND name = 'Vivienda');
